    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 v) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (v)); require(v <= 1000000000000000000000000000000);
        require(v > 0, "need positive value");
        require(address(this).balance >= v, "not enough balance");
        address target = 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C;
        uint256 targetBefore = target.balance;
        bool reverted;
        c.go{value: v}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(reverted || (target.balance == targetBefore + v && address(c).balance == 0));
    }

    receive() external payable {}
