pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {B} from "../src/B.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    B c;

    function setUp() public {
        c = new B();
    }

    function _run(uint256 v) internal {
        v = bound(v, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(v > 0);
        vm.assume(address(this).balance >= v);
        address target = 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C;
        uint256 targetBefore = target.balance;
        bool reverted;
        try c.go{value: v}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted || (target.balance == targetBefore + v && address(c).balance == 0));
    }

    function testFuzz_run(uint256 v) public {
        _run(v);
    }

    receive() external payable {}
}
